macro_rules! Clear {
    () => {
        # [doc = " Trait implemented by types which can be cleared in place, retaining any"] # [doc = " allocated memory."] # [doc = ""] # [doc = " This is essentially a generalization of methods on standard library"] # [doc = " collection types, including as [`Vec::clear`], [`String::clear`], and"] # [doc = " [`HashMap::clear`]. These methods drop all data stored in the collection,"] # [doc = " but retain the collection's heap allocation for future use. Types such as"] # [doc = " `BTreeMap`, whose `clear` methods drops allocations, should not"] # [doc = " implement this trait."] # [doc = ""] # [doc = " When implemented for types which do not own a heap allocation, `Clear`"] # [doc = " should reset the type in place if possible. If the type has an empty state"] # [doc = " or stores `Option`s, those values should be reset to the empty state. For"] # [doc = " \"plain old data\" types, which hold no pointers to other data and do not have"] # [doc = " an empty or initial state, it's okay for a `Clear` implementation to be a"] # [doc = " no-op. In that case, it essentially serves as a marker indicating that the"] # [doc = " type may be reused to store new data."] # [doc = ""] # [doc = " [`Vec::clear`]: https://doc.rust-lang.org/stable/std/vec/struct.Vec.html#method.clear"] # [doc = " [`String::clear`]: https://doc.rust-lang.org/stable/std/string/struct.String.html#method.clear"] # [doc = " [`HashMap::clear`]: https://doc.rust-lang.org/stable/std/collections/struct.HashMap.html#method.clear"] pub trait Clear { # [doc = " Clear all data in `self`, retaining the allocated capacithy."] fn clear (& mut self) ; }
    };
}

Clear!()